		},
		handoff: [
			{
				EventId: fact.eventId,
				Edition: edition,
				Mode: correction ? 'correction' : 'original',
				Date: fact.date,
				CurrentResult: line,
				PreviousResult: previousLine,
				PreviousVideoUrl: published?.row.VideoUrl || '',
